def compute_posteriors(mode="conservative"):
    logw = {}
    for eid in sorted(d2_3_recipients - {decoy}):
        dept = emp_by_id[eid]["dept"]
        lw = 0.0
        for d in [1, 2, 3, 4]:
            if d == 1 and dept == "Legal":
                continue
            n_reg = sum(1 for x in logs if x["day"] == d and x["employee"] == eid and not x["after_hours"])
            n_ah = sum(1 for x in logs if x["day"] == d and x["employee"] == eid and x["after_hours"])
            lam_ah_inn = 0.1 + (1.0 / (31.0 if d == 1 else 38.0))
            lw += n_reg * math.log(0.7 / 0.9) - (0.7 - 0.9)
            lw += n_ah * math.log(0.3 / lam_ah_inn) - (0.3 - lam_ah_inn)
        for ie, ev in interviews:
            if ie == eid:
                lw += math.log(0.24 / 0.20) if ev else math.log(0.76 / 0.80)
        if mode == "random_mole":
            # Day 1 no leak (0.35 vs 1.0), Day 2 d2-3 (1/6 vs 1/3), Day 3 d2-1 (1/7 vs 1/2) => Legal gets 20x vs Eng!
            if dept != "Legal":
                lw += math.log(0.35 * (1/6) * (1/7) / (1.0 * (1/3) * (1/2)))
        logw[eid] = lw
    m = max(logw.values())
    w = {k: math.exp(v - m) for k, v in logw.items()}
    s = sum(w.values())
    return {k: v / s for k, v in sorted(w.items(), key=lambda kv: -kv[1])}
